<script>
  // BILLING TOGGLE
  const toggle = document.getElementById('billingToggle');
  const monthlyLabel = document.getElementById('monthlyLabel');
  const annualLabel = document.getElementById('annualLabel');

  const prices = {
    business: { monthly: 18, annual: 15 },
    ai: { monthly: 24, annual: 20 }
  };

  function updatePrices() {
    const isAnnual = toggle.checked;
    monthlyLabel.classList.toggle('active', !isAnnual);
    annualLabel.classList.toggle('active', isAnnual);

    const bPrice = isAnnual ? prices.business.annual : prices.business.monthly;
    const aPrice = isAnnual ? prices.ai.annual : prices.ai.monthly;

    document.getElementById('businessPrice').textContent = '$' + bPrice;
    document.getElementById('aiPrice').textContent = '$' + aPrice;
    document.getElementById('businessUnit').textContent = '/user/month';
    document.getElementById('aiUnit').textContent = '/user/month';
    document.getElementById('businessTotal').textContent = isAnnual ? 'billed annually · $18/mo if monthly' : 'billed monthly · save 17% annually';
    document.getElementById('aiTotal').textContent = isAnnual ? 'billed annually · $24/mo if monthly' : 'billed monthly · save 17% annually';

    updateTeamBilling();
  }

  toggle.addEventListener('change', updatePrices);

  // TEAM SIZE SLIDER
  const slider = document.getElementById('teamSlider');
  const teamDisplay = document.getElementById('teamSizeDisplay');

  function updateTeamBilling() {
    const size = parseInt(slider.value);
    teamDisplay.textContent = size + ' user' + (size === 1 ? '' : 's');
    const isAnnual = toggle.checked;
    const bPrice = isAnnual ? prices.business.annual : prices.business.monthly;
    const aPrice = isAnnual ? prices.ai.annual : prices.ai.monthly;
    const mult = isAnnual ? 12 : 1;
    const bTotal = (bPrice * size * mult).toLocaleString();
    const period = isAnnual ? '/yr' : '/mo';
    document.getElementById('teamBillingTotal').textContent = '$' + bTotal + period;
    const pct = ((size - 1) / 199 * 100).toFixed(1);
    slider.style.background = `linear-gradient(to right, var(--blue) ${pct}%, var(--border) ${pct}%)`;
    if (size >= 100) {
      document.getElementById('teamHint').innerHTML = 'For teams of 100+, <a href="#" style="color:var(--blue);font-weight:600;">contact sales</a> for custom Enterprise pricing.';
    } else {
      document.getElementById('teamHint').innerHTML = 'Billing total: <strong id="teamBillingTotal">$' + bTotal + period + '</strong> for Business plan';
    }
  }

  slider.addEventListener('input', updateTeamBilling);
  updateTeamBilling();

  // FAQ ACCORDION
  function toggleFaq(id) {
    const item = document.getElementById(id);
    const wasOpen = item.classList.contains('open');
    document.querySelectorAll('.faq-item').forEach(el => el.classList.remove('open'));
    if (!wasOpen) item.classList.add('open');
  }

  // COMPARISON TABLE EXPAND
  let tableExpanded = false;
  function toggleTable() {
    tableExpanded = !tableExpanded;
    const hiddenRows = document.querySelectorAll('.table-row-hidden');
    hiddenRows.forEach(row => row.classList.toggle('visible', tableExpanded));
    const btn = document.getElementById('expandBtn');
    const icon = document.getElementById('expandIcon');
    btn.innerHTML = tableExpanded
      ? '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M18 15l-6-6-6 6"/></svg> Hide features'
      : '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M6 9l6 6 6-6"/></svg> See all features';
  }
</script>
